ALTER TABLE accounts ALTER COLUMN password_hash DROP NOT NULL;
ALTER TABLE accounts ADD COLUMN google_subject TEXT UNIQUE;
ALTER TABLE accounts ADD COLUMN suspended BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE accounts ADD COLUMN consent_version TEXT;
ALTER TABLE accounts ADD COLUMN consent_at TIMESTAMPTZ;
CREATE TABLE sessions (id UUID PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES accounts ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE invitations (email TEXT PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE settings (id INT PRIMARY KEY CHECK(id=1), invitations_paused BOOLEAN NOT NULL DEFAULT false);
INSERT INTO settings(id) VALUES(1);
CREATE TABLE blocks (actor BIGINT REFERENCES accounts ON DELETE CASCADE, target BIGINT REFERENCES accounts ON DELETE CASCADE, PRIMARY KEY(actor,target), CHECK(actor<>target));
CREATE TABLE conversations (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, low_id BIGINT NOT NULL REFERENCES accounts ON DELETE CASCADE, high_id BIGINT NOT NULL REFERENCES accounts ON DELETE CASCADE, closed BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(low_id,high_id), CHECK(low_id<high_id));
INSERT INTO conversations(low_id,high_id) SELECT a.actor_id,a.target_id FROM decisions a JOIN decisions b ON a.actor_id=b.target_id AND a.target_id=b.actor_id WHERE a.liked AND b.liked AND a.actor_id<a.target_id;
CREATE TABLE messages (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL REFERENCES conversations ON DELETE CASCADE, sender BIGINT NOT NULL REFERENCES accounts ON DELETE CASCADE, client_id UUID NOT NULL, body VARCHAR(2000) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(sender,client_id));
CREATE INDEX messages_history ON messages(conversation_id,id);
CREATE TABLE activities (conversation_id BIGINT PRIMARY KEY REFERENCES conversations ON DELETE CASCADE, proposer BIGINT NOT NULL REFERENCES accounts ON DELETE CASCADE, accepted BOOLEAN NOT NULL DEFAULT false, round INT NOT NULL DEFAULT 0 CHECK(round BETWEEN 0 AND 3));
CREATE TABLE answers (conversation_id BIGINT REFERENCES conversations ON DELETE CASCADE, round INT NOT NULL, user_id BIGINT REFERENCES accounts ON DELETE CASCADE, body VARCHAR(500) NOT NULL, PRIMARY KEY(conversation_id,round,user_id));
CREATE TABLE rounds (conversation_id BIGINT REFERENCES conversations ON DELETE CASCADE, round INT NOT NULL, state TEXT NOT NULL CHECK(state IN ('revealed','skipped')), PRIMARY KEY(conversation_id,round));
CREATE TABLE photos (user_id BIGINT PRIMARY KEY REFERENCES accounts ON DELETE CASCADE, bytes BYTEA NOT NULL);
CREATE TABLE reports (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, reporter BIGINT REFERENCES accounts ON DELETE SET NULL, target BIGINT REFERENCES accounts ON DELETE SET NULL, reason VARCHAR(1000) NOT NULL, evidence TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL DEFAULT now()+INTERVAL '30 days');
CREATE TABLE audit (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor BIGINT REFERENCES accounts ON DELETE SET NULL, action TEXT NOT NULL, target TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE events (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES accounts ON DELETE CASCADE, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
